import operator


_OPERATIONS = {
    "plus": operator.add,
    "minus": operator.sub,
    "multiplied by": operator.mul,
    "divided by": operator.floordiv,
}


def _is_number(token):
    if token.startswith("-"):
        token = token[1:]
    return bool(token) and token.isascii() and token.isdigit()


def _merge_operations(words):
    tokens = []
    index = 0

    while index < len(words):
        word = words[index]
        if (
            word in ("multiplied", "divided")
            and index + 1 < len(words)
            and words[index + 1] == "by"
        ):
            tokens.append(f"{word} by")
            index += 2
        else:
            tokens.append(word)
            index += 1

    return tokens


def answer(question):
    if not isinstance(question, str):
        raise ValueError("unknown operation")

    if question == "What is?":
        raise ValueError("syntax error")
    if not question.startswith("What is ") or not question.endswith("?"):
        raise ValueError("unknown operation")

    body = question[len("What is ") : -1].strip()
    if not body:
        raise ValueError("syntax error")

    tokens = _merge_operations(body.split())
    if any(not _is_number(token) and token not in _OPERATIONS for token in tokens):
        raise ValueError("unknown operation")

    if not _is_number(tokens[0]):
        raise ValueError("syntax error")

    result = int(tokens[0])
    index = 1
    while index < len(tokens):
        if (
            index + 1 >= len(tokens)
            or tokens[index] not in _OPERATIONS
            or not _is_number(tokens[index + 1])
        ):
            raise ValueError("syntax error")

        result = _OPERATIONS[tokens[index]](result, int(tokens[index + 1]))
        index += 2

    return result

